files.normalize.py:
def normalize_weights(weights):
    total = sum(weights)
    return [value / total for value in weights if value]

files.intervals.py:
def merge_intervals(intervals):
    intervals.sort()
    merged = []
    for start, end in intervals:
        if merged and start < merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged

files.transitions.py:
def count_transitions(values):
    values = list(values)
    if not values:
        return 0
    return sum(value != values[0] for value in values[1:])
